// Generate flagUrl for each country (using flagcdn or svg data URL)
allCountries.forEach(c => {
  const code = c.id.toLowerCase();
  c.flagUrl = `https://flagcdn.com/${code.slice(0, 2)}.svg`;
});

const fileContent = `/**
 * Comprehensive Sovereign Nations Dataset for GeoQuest Engine
 * 196 recognized sovereign nations with geographical, demographic, and political data.
 */

import { CountryRecord } from './types';

export const COUNTRIES: CountryRecord[] = ${JSON.stringify(allCountries, null, 2)};

export const COUNTRIES_BY_ID = new Map<string, CountryRecord>(
  COUNTRIES.map((c) => [c.id, c])
);

export const COUNTRIES_BY_NUMERIC_ID = new Map<string, CountryRecord>(
  COUNTRIES.map((c) => [String(Number(c.numericId) || c.numericId), c])
);
`;

fs.writeFileSync(path.join(__dirname, '../src/data/countries.ts'), fileContent, 'utf8');
console.log('Successfully wrote src/data/countries.ts with', allCountries.length, 'countries!');
